package com.progressly.activity.api; import com.progressly.activity.domain.*; import java.time.LocalDate; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class HabitService{final HabitRepository habits;final HabitLogRepository logs;public HabitService(HabitRepository h,HabitLogRepository l){habits=h;logs=l;} @Transactional public HabitDtos.Response create(UUID u,HabitDtos.Request r){return out(habits.save(new Habit(u,r.name().trim(),r.description(),r.frequency(),r.targetValue())));} @Transactional(readOnly=true) public List<HabitDtos.Response> list(UUID u){return habits.findByUserIdAndActiveTrueOrderByCreatedAtDesc(u).stream().map(this::out).toList();} @Transactional public HabitDtos.Response update(UUID u,UUID id,HabitDtos.Request r){Habit h=find(u,id);h.update(r.name().trim(),r.description(),r.frequency(),r.targetValue());return out(habits.save(h));} @Transactional public void delete(UUID u,UUID id){Habit h=find(u,id);h.active(false);habits.save(h);} @Transactional public HabitDtos.LogResponse log(UUID u,UUID id,HabitDtos.LogRequest r){find(u,id);LocalDate date=r.date()==null?LocalDate.now():r.date();HabitLog l=logs.findByHabitIdAndUserIdAndLogDate(id,u,date).orElseGet(()->new HabitLog(id,u,date,r.completed(),r.value()));l.update(r.completed(),r.value());return log(logs.save(l));} @Transactional(readOnly=true) public List<HabitDtos.LogResponse> history(UUID u,UUID id){find(u,id);return logs.findByHabitIdAndUserIdOrderByLogDateDesc(id,u).stream().map(this::log).toList();} private Habit find(UUID u,UUID id){return habits.findByIdAndUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Habit not found"));} private HabitDtos.Response out(Habit h){return new HabitDtos.Response(h.getId(),h.getName(),h.getDescription(),h.getFrequency(),h.getTargetValue(),h.isActive(),h.getCreatedAt());} private HabitDtos.LogResponse log(HabitLog l){return new HabitDtos.LogResponse(l.getId(),l.getHabitId(),l.getLogDate(),l.isCompleted(),l.getValue());}}
